args.command:
pkill -f "vite preview" 2>/dev/null; cat > /tmp/e2e/storage-check.mjs <<'EOF'
const mem = new Map();
globalThis.localStorage = {
  getItem: (k) => (mem.has(k) ? mem.get(k) : null),
  setItem: (k, v) => mem.set(k, String(v)),
};
const { loadThemeChoice, saveThemeChoice, THEME_STORAGE_KEY } = await import('/home/sandbox/workspace/src/theme.ts');
const out = [];
const eq = (name, a, b) => out.push(`${a === b ? 'PASS' : 'FAIL'} ${name}: got ${JSON.stringify(a)}`);
eq('empty storage -> light', loadThemeChoice(), 'light');
saveThemeChoice('dark');
eq('stored dark is persisted under key', mem.get(THEME_STORAGE_KEY), 'dark');
eq('load after save -> dark', loadThemeChoice(), 'dark');
saveThemeChoice('system');
eq('load after save -> system', loadThemeChoice(), 'system');
mem.set(THEME_STORAGE_KEY, 'purple');
eq('invalid value -> light', loadThemeChoice(), 'light');
globalThis.localStorage = { getItem() { throw new Error('denied'); }, setItem() { throw new Error('denied'); } };
eq('storage throws on read -> light', loadThemeChoice(), 'light');
let threw = false; try { saveThemeChoice('dark'); } catch { threw = true; }
eq('storage throws on write -> no exception', threw, false);
console.log(out.join('\n'));
EOF
cd /tmp/e2e && node --experimental-strip-types storage-check.mjs 2>&1 | grep -v ExperimentalWarning

